class Solution:
    def totalSteps(self, nums: list[int]) -> int:
        stk = []
        ans = 0
        for x in reversed(nums):
            steps = 0
            while stk and x > stk[-1][0]:
                steps = max(steps + 1, stk[-1][1])
                stk.pop()
            stk.append((x, steps))
            ans = max(ans, steps)
        return ans

class Solution {
public:
    int totalSteps(std::vector<int>& nums) {
        std::vector<std::pair<int, int>> stk;
        int ans = 0;
        for (int i = (int)nums.size() - 1; i >= 0; --i) {
            int steps = 0;
            while (!stk.empty() && nums[i] > stk.back().first) {
                steps = std::max(steps + 1, stk.back().second);
                stk.pop_back();
            }
            stk.push_back({nums[i], steps});
            ans = std::max(ans, steps);
        }
        return ans;
    }
};

class Solution {
    public int totalSteps(int[] nums) {
        int n = nums.length;
        int[] vals = new int[n];
        int[] stepArr = new int[n];
        int top = -1;
        int ans = 0;
        for (int i = n - 1; i >= 0; i--) {
            int steps = 0;
            while (top >= 0 && nums[i] > vals[top]) {
                steps = Math.max(steps + 1, stepArr[top]);
                top--;
            }
            top++;
            vals[top] = nums[i];
            stepArr[top] = steps;
            ans = Math.max(ans, steps);
        }
        return ans;
    }
}

var totalSteps = function(nums) {
    const stk = [];
    let ans = 0;
    for (let i = nums.length - 1; i >= 0; i--) {
        let steps = 0;
        while (stk.length > 0 && nums[i] > stk[stk.length - 1][0]) {
            steps = Math.max(steps + 1, stk[stk.length - 1][1]);
            stk.pop();
        }
        stk.push([nums[i], steps]);
        if (steps > ans) ans = steps;
    }
    return ans;
};
